window.SHEETS=[{"id": "fortigate-cli-essentials", "title": "FortiGate CLI essentials", "vendor": "Fortinet", "category": "Cybersecurity", "description": "The everyday commands for finding your way around a FortiGate.", "rows": [["get system status", "Identify firmware and device information"], ["get system performance status", "Inspect CPU, memory and uptime"], ["get system interface", "Inspect interface information"], ["get system arp", "Inspect learned IPv4 neighbors"], ["get router info routing-table all", "Inspect active routes"]], "source": "https://docs.fortinet.com/document/fortigate/7.4.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet", "level": "Beginner", "time": 4, "product": "FortiGate", "updated": "2026-11-01"}, {"id": "cisco-ios-essentials", "title": "Cisco IOS essentials", "vendor": "Cisco", "category": "Networking", "description": "Get oriented, inspect interfaces, and understand your device.", "rows": [["show version", "Identify software and device information"], ["show ip interface brief", "Check interface addresses and status"], ["show interfaces", "Inspect interface counters"], ["show running-config", "Review active configuration"], ["show inventory", "List hardware inventory"]], "source": "https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9400/software/release/26-x/command_reference/b_26x_9400_cr/interface_and_hardware_commands.html", "level": "Beginner", "time": 5, "product": "Cisco", "updated": "2026-11-01"}, {"id": "fortigate-routing-arp", "title": "FortiGate routing & ARP", "vendor": "Fortinet", "category": "Networking", "description": "Follow a packet from its next hop to the routing table.", "rows": [["get router info routing-table all", "Inspect active routes"], ["get system arp", "Resolve local neighbors"], ["diagnose ip arp list", "Inspect detailed ARP entries"], ["diagnose ip route list", "Inspect kernel routes"]], "source": "https://docs.fortinet.com/document/fortigate/7.4.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet", "level": "Beginner", "time": 6, "product": "FortiGate", "updated": "2026-11-01"}, {"id": "cisco-interface-diagnostics", "title": "Cisco interface diagnostics", "vendor": "Cisco", "category": "Networking", "description": "Find link failures and read the counters that matter.", "rows": [["show ip interface brief", "Summarize interface state"], ["show interfaces status", "Inspect switch port status"], ["show interfaces counters errors", "Inspect switch errors"], ["show interfaces description", "Inspect configured descriptions"]], "source": "https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9400/software/release/26-x/command_reference/b_26x_9400_cr/interface_and_hardware_commands.html", "level": "Beginner", "time": 7, "product": "Cisco", "updated": "2026-11-01"}, {"id": "fortigate-vpn-health", "title": "FortiGate VPN health", "vendor": "Fortinet", "category": "Cybersecurity", "description": "Inspect IPsec tunnel health and security associations.", "rows": [["get vpn ipsec tunnel summary", "Summarize tunnel state"], ["diagnose vpn tunnel list", "Inspect IPsec tunnel details"], ["diagnose vpn ike gateway list", "Inspect IKE gateways"], ["diagnose vpn ipsec status", "Inspect IPsec status"]], "source": "https://docs.fortinet.com/document/fortigate/7.4.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet", "level": "Beginner", "time": 4, "product": "FortiGate", "updated": "2026-11-01"}, {"id": "cisco-vlans-trunks", "title": "Cisco VLANs & trunks", "vendor": "Cisco", "category": "Networking", "description": "Understand access VLANs, tagged links, and Layer 2 boundaries.", "rows": [["show vlan brief", "Inspect VLAN membership"], ["show interfaces trunk", "Inspect trunk status"], ["show interfaces switchport", "Inspect switchport settings"], ["show spanning-tree", "Inspect spanning tree state"]], "source": "https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9400/software/release/26-x/command_reference/b_26x_9400_cr/interface_and_hardware_commands.html", "level": "Beginner", "time": 5, "product": "Cisco", "updated": "2026-11-01"}, {"id": "fortigate-ha-system-health", "title": "FortiGate HA & system health", "vendor": "Fortinet", "category": "Cybersecurity", "description": "Check cluster membership and baseline appliance health.", "rows": [["get system ha status", "Inspect cluster members"], ["get system performance status", "Inspect resource usage"], ["diagnose sys ntp status", "Inspect time synchronization"], ["get system status", "Identify firmware"]], "source": "https://docs.fortinet.com/document/fortigate/7.4.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet", "level": "Beginner", "time": 6, "product": "FortiGate", "updated": "2026-11-01"}, {"id": "cisco-routing-basics", "title": "Cisco routing basics", "vendor": "Cisco", "category": "Networking", "description": "Read connected, static, and learned routes with confidence.", "rows": [["show ip route", "Inspect IPv4 routes"], ["show ip protocols", "Inspect routing protocols"], ["show ip arp", "Inspect IPv4 neighbors"], ["show ip interface brief", "Inspect interface status"]], "source": "https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9400/software/release/26-x/command_reference/b_26x_9400_cr/interface_and_hardware_commands.html", "level": "Beginner", "time": 7, "product": "Cisco", "updated": "2026-11-01"}, {"id": "fortigate-session-inspection", "title": "FortiGate session inspection", "vendor": "Fortinet", "category": "Cybersecurity", "description": "Connect policy decisions with live traffic sessions.", "rows": [["get system session status", "Inspect session totals"], ["diagnose sys session stat", "Inspect session statistics"], ["diagnose sys session list", "Inspect session entries"], ["get system performance status", "Inspect appliance load"]], "source": "https://docs.fortinet.com/document/fortigate/7.4.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet", "level": "Beginner", "time": 4, "product": "FortiGate", "updated": "2026-11-01"}, {"id": "cisco-neighbor-discovery", "title": "Cisco neighbor discovery", "vendor": "Cisco", "category": "Networking", "description": "Map the devices directly connected to your switch.", "rows": [["show cdp neighbors", "List Cisco discovery neighbors"], ["show cdp neighbors detail", "Inspect neighbor details"], ["show lldp neighbors", "List LLDP neighbors"], ["show lldp neighbors detail", "Inspect LLDP details"]], "source": "https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9400/software/release/26-x/command_reference/b_26x_9400_cr/interface_and_hardware_commands.html", "level": "Beginner", "time": 5, "product": "Cisco", "updated": "2026-11-01"}, {"id": "linux-network-essentials", "title": "Linux network essentials", "vendor": "Linux", "category": "IT fundamentals", "description": "A small toolkit for inspecting a Linux host\u2019s network.", "rows": [["ip address show", "Inspect interface addresses"], ["ip route show", "Inspect routing table"], ["ip neigh show", "Inspect neighbors"], ["ss -tuln", "Inspect listening TCP and UDP sockets"]], "source": "https://man7.org/linux/man-pages/man8/ip.8.html", "level": "Beginner", "time": 6, "product": "Linux", "updated": "2026-11-01"}, {"id": "cloud-network-fundamentals", "title": "Cloud network fundamentals", "vendor": "Vendor neutral", "category": "Cloud", "description": "Connect subnets, routes, security rules, and DNS into one model.", "rows": [["CIDR", "An address prefix defines a network range"], ["Subnet", "A segment of a virtual network"], ["Route table", "Maps destination prefixes to next hops"], ["Security group", "Controls permitted traffic for associated resources"], ["Private DNS", "Resolves internal service names"]], "source": "https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html", "level": "Beginner", "time": 7, "product": "Vendor neutral", "updated": "2026-11-01"}, {"id": "windows-network-troubleshooting", "title": "Windows network troubleshooting", "product": "Windows", "vendor": "Windows", "category": "IT fundamentals", "description": "Inspect addressing, DNS resolution and TCP reachability with PowerShell.", "scope": "Windows 10/11 and Windows Server with NetTCPIP and DnsClient modules.", "prerequisites": "Open PowerShell on the affected host. Replace server.example.com with an approved test host; TCP tests send probes.", "source": "https://learn.microsoft.com/en-us/powershell/module/nettcpip/", "sourceLabel": "Windows official documentation", "rows": [["Get-NetIPConfiguration", "Inspect addresses and gateways"], ["Get-NetAdapter", "Inspect adapter state and link speed"], ["Resolve-DnsName server.example.com", "Resolve a host name"], ["Test-NetConnection server.example.com -Port 443", "Test a specific TCP service"]], "walkthrough": ["Find the adapter carrying the affected traffic. Compare its address, default gateway and DNS servers with the intended subnet. Disconnected adapters may appear alongside the active one.", "Match the interface name to the physical or virtual adapter. A disconnected interface points to a link or virtual-switch issue before DNS becomes relevant.", "Replace the example name with your target. Check the answer and record whether the response is NXDOMAIN, a timeout or an unexpected address; these indicate different failure paths.", "Check TcpTestSucceeded and the selected source address. A successful test confirms a TCP connection, not application authentication or TLS correctness."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "windows-services-and-event-logs", "title": "Windows services and event logs", "product": "Windows", "vendor": "Windows", "category": "IT fundamentals", "description": "Build a focused picture of service state and recent system errors.", "scope": "Windows PowerShell 5.1 or supported PowerShell on Windows.", "prerequisites": "Use an account permitted to read the selected event log. These commands do not start or stop services.", "source": "https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.diagnostics/get-winevent", "sourceLabel": "Windows official documentation", "rows": [["Get-Service", "List service states"], ["Get-Service -Name Spooler", "Inspect a specific service"], ["Get-WinEvent -FilterHashtable @{LogName='System'; Level=2; StartTime=(Get-Date).AddHours(-2)} -MaxEvents 30", "Read recent system errors"], ["Get-Process | Sort-Object CPU -Descending | Select-Object -First 10", "Inspect cumulative CPU usage"]], "walkthrough": ["Find the affected service and its actual status. A stopped service may be intentional; compare against its startup policy and the application runbook.", "This example checks Print Spooler. Substitute the service name, not its display label. Record status before considering any restart.", "Correlate provider, event ID and timestamp with the incident. No matches is different from access denied or a missing log; preserve the distinction.", "CPU here is accumulated processor time since each process started. It is not a live utilization percentage; confirm a suspected spike with Performance Monitor."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "active-directory-users-and-groups", "title": "Active Directory users and groups", "product": "Active Directory", "vendor": "Active Directory", "category": "Identity & Microsoft 365", "description": "Inspect domain identity, user status and group membership using RSAT.", "scope": "On-premises Active Directory Domain Services; ActiveDirectory PowerShell module.", "prerequisites": "Install RSAT through your approved software process. Use a domain-connected administrative workstation and an account with directory read access.", "source": "https://learn.microsoft.com/en-us/powershell/module/activedirectory/", "sourceLabel": "Active Directory official documentation", "rows": [["Get-ADDomain", "Identify the current domain"], ["Get-ADUser -Identity 'jdoe' -Properties Enabled,LockedOut,PasswordLastSet", "Inspect a user account"], ["Get-ADPrincipalGroupMembership -Identity 'jdoe'", "List principal group memberships"], ["Get-ADGroupMember -Identity 'Helpdesk'", "Inspect direct group members"]], "walkthrough": ["Confirm DNSRoot, distinguished name and domain controllers. Querying the wrong domain can look like a missing user.", "Replace jdoe with a real sAMAccountName. Compare Enabled and LockedOut separately; neither field alone proves that sign-in will succeed.", "Review returned groups against expected access. This list is not a complete effective-access calculation across ACLs, claims and all resource domains.", "Replace the example group. This returns direct membership; nested groups need separate inspection or the -Recursive parameter."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "active-directory-replication-health", "title": "Active Directory replication health", "product": "Active Directory", "vendor": "Active Directory", "category": "Identity & Microsoft 365", "description": "Compare domain-controller replication and locate recent failures.", "scope": "AD DS with RSAT ActiveDirectory module and repadmin available.", "prerequisites": "Run from an authorized domain administration workstation with network reachability to domain controllers. Collect results before changing replication topology.", "source": "https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adreplicationfailure", "sourceLabel": "Active Directory official documentation", "rows": [["Get-ADDomainController -Filter *", "List domain controllers"], ["Get-ADReplicationFailure -Target 'corp.example.com' -Scope Domain", "Inspect recorded replication failures"], ["repadmin /replsummary", "Summarize replication failures"], ["repadmin /showrepl", "Inspect local controller replication partners"]], "walkthrough": ["Compare host names and site assignments with your topology. Confirm whether an affected controller is reachable before interpreting replication failures.", "Replace the example domain. Record the partner, error code, first failure time and failure count. Empty output does not independently certify overall directory health.", "Compare failed attempts and largest delta across sources and destinations. Investigate persistent deltas against the configured site-link schedule.", "Run on the controller you are investigating or specify the intended controller per repadmin help. Correlate last successful replication with the incident window."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "microsoft-graph-connection-and-user-lookup", "title": "Microsoft Graph connection and user lookup", "product": "Microsoft Graph", "vendor": "Microsoft Graph", "category": "Identity & Microsoft 365", "description": "Connect to the correct tenant and inspect directory user records.", "scope": "Microsoft Graph PowerShell SDK v1.0 commands, delegated authentication.", "prerequisites": "Use approved Microsoft.Graph.Authentication and Microsoft.Graph.Users modules. User.Read.All needs administrator consent; use an already authorized app and account.", "source": "https://learn.microsoft.com/en-us/powershell/microsoftgraph/authentication-commands", "sourceLabel": "Microsoft Graph official documentation", "rows": [["Connect-MgGraph -Scopes 'User.Read.All' -ContextScope Process", "Authenticate for directory reads"], ["Get-MgContext", "Verify tenant and granted scopes"], ["Get-MgUser -UserId 'user@example.com' -Property Id,DisplayName,UserPrincipalName,AccountEnabled", "Read a specific user"], ["Disconnect-MgGraph", "End the Graph session"]], "walkthrough": ["Complete interactive authentication for your approved tenant. The process scope avoids persisting this session context beyond the PowerShell process. Follow your administrator\u2019s consent process if prompted.", "Check TenantId, Account and Scopes before running queries. Stop if the identity or tenant differs from your intended environment.", "Replace the example UPN. Requesting AccountEnabled explicitly avoids relying on the default property set. An authorization error is not evidence that the account is missing.", "Disconnect when the investigation is complete. Store only the minimum necessary findings; user identifiers and account states are organizational data."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "microsoft-graph-query-and-paging-basics", "title": "Microsoft Graph query and paging basics", "product": "Microsoft Graph", "vendor": "Microsoft Graph", "category": "Identity & Microsoft 365", "description": "Find users with server-side filters and handle complete result sets.", "scope": "Graph PowerShell Microsoft.Graph.Users; delegated User.Read.All.", "prerequisites": "Connect using the connection guide, verify Get-MgContext and use a tenant where directory reading is authorized.", "source": "https://learn.microsoft.com/en-us/powershell/module/microsoft.graph.users/get-mguser", "sourceLabel": "Microsoft Graph official documentation", "rows": [["Get-MgContext", "Confirm query context"], ["Get-MgUser -Filter \"startsWith(displayName,'Alex')\" -Top 10", "Find a bounded set of matching users"], ["Get-MgUser -All -Property Id,DisplayName,UserPrincipalName", "Retrieve all result pages"], ["Get-MgUser -UserId 'user@example.com' -Property Id,AssignedLicenses", "Inspect assigned license identifiers"]], "walkthrough": ["Confirm the tenant and User.Read.All scope. The query examples below read user records and do not alter the directory.", "Replace Alex with a relevant prefix. The filter is sent to Graph; Top 10 deliberately limits the returned sample and is not a tenant-wide count.", "Use only when a full user inventory is needed. -All traverses pages and can take time in large tenants; protect the resulting personal data.", "Replace the UPN and inspect AssignedLicenses. SKU IDs need mapping to tenant license products; an assigned license alone does not establish service provisioning health."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "entra-id-sign-in-investigation", "title": "Entra ID sign-in investigation", "product": "Entra ID", "vendor": "Entra ID", "category": "Identity & Microsoft 365", "description": "Review recent sign-ins and distinguish authentication from policy failures.", "scope": "Microsoft Entra admin center sign-in logs. Labels can vary by portal release.", "prerequisites": "Use at least an appropriate log-reading role such as Reports Reader. Available history and fields depend on licensing and retention.", "source": "https://learn.microsoft.com/en-us/entra/identity/monitoring-health/howto-analyze-activity-logs", "sourceLabel": "Entra ID official documentation", "rows": [["Entra ID \u2192 Monitoring & health \u2192 Sign-in logs", "Open sign-in activity"], ["Filter by user, date and status", "Isolate the reported attempt"], ["Open event \u2192 Basic info / Authentication details", "Read the authentication outcome"], ["Open event \u2192 Conditional Access", "Inspect applied policy results"]], "walkthrough": ["Select the affected tenant first. Limit the time window and user so you do not mistake unrelated background sign-ins for the reported attempt.", "Record the timestamp and time zone, application and correlation ID. Ask the user for the precise attempt time if multiple failures exist.", "Compare the failure reason with individual authentication steps. A successful first factor may still be followed by an MFA or policy failure.", "Inspect each evaluated policy and grant control. Report-only results do not enforce a block; do not disable policies as a diagnostic shortcut."], "kind": "Console path", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "entra-id-devices-and-tenant-overview", "title": "Entra ID devices and tenant overview", "product": "Entra ID", "vendor": "Entra ID", "category": "Identity & Microsoft 365", "description": "Inspect tenant context, device identities and join state without changing access.", "scope": "Microsoft Entra admin center and Windows dsregcmd.", "prerequisites": "Use directory read access appropriate for the tenant. Run dsregcmd /status as the affected signed-in Windows user.", "source": "https://learn.microsoft.com/en-us/entra/identity/devices/troubleshoot-device-dsregcmd", "sourceLabel": "Entra ID official documentation", "rows": [["Entra ID \u2192 Overview", "Confirm tenant identity"], ["Entra ID \u2192 Devices \u2192 All devices", "Locate the device object"], ["dsregcmd /status", "Inspect the local registration state"], ["Review Device State and SSO State sections", "Compare identity and sign-in state"]], "walkthrough": ["Record the tenant ID and primary domain. Multiple tenants in the same browser session can lead to inspecting a similarly named but unrelated directory.", "Search the device name and compare its device ID. Check enabled state, join type and last activity; duplicate names do not imply duplicate identities.", "On the Windows device, compare AzureAdJoined, DomainJoined, TenantId and DeviceId with the portal. The command reads local registration state and does not join or leave the tenant.", "Device join and a user\u2019s primary refresh token are separate observations. Record AzureAdPrt in the user context; a device object existing in Entra does not prove healthy SSO."], "kind": "Command / console path", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "exchange-online-mailbox-inspection", "title": "Exchange Online mailbox inspection", "product": "Exchange Online", "vendor": "Exchange Online", "category": "Identity & Microsoft 365", "description": "Connect to Exchange Online and review mailbox identity and quotas.", "scope": "ExchangeOnlineManagement module; Exchange Online PowerShell.", "prerequisites": "Use an approved Exchange Online account with the required RBAC read permissions. Replace user@example.com with the target mailbox.", "source": "https://learn.microsoft.com/en-us/powershell/module/exchange/get-exomailbox", "sourceLabel": "Exchange Online official documentation", "rows": [["Connect-ExchangeOnline", "Open an authenticated Exchange session"], ["Get-EXOMailbox -Identity 'user@example.com'", "Inspect mailbox identity"], ["Get-EXOMailbox -Identity 'user@example.com' -Properties IssueWarningQuota,ProhibitSendQuota", "Read mailbox quota settings"], ["Disconnect-ExchangeOnline -Confirm:$false", "Close the PowerShell session"]], "walkthrough": ["Complete interactive authentication using your approved admin identity. Verify you are connecting to the intended organization before inspecting recipients.", "Compare primary SMTP address and recipient type with the reported mailbox. A mail-enabled user and an Exchange Online mailbox are different recipient types.", "Request the non-default quota properties explicitly. Compare configured quotas with actual mailbox size before concluding that quota enforcement is causing the issue.", "End the session after capturing necessary findings. This disconnects the administrative session; it does not disconnect mailbox users."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "exchange-online-message-tracing", "title": "Exchange Online message tracing", "product": "Exchange Online", "vendor": "Exchange Online", "category": "Identity & Microsoft 365", "description": "Trace a recent sender and examine the events for a specific message.", "scope": "Exchange Online Get-MessageTraceV2; ExchangeOnlineManagement 3.7.0 or later.", "prerequisites": "Connect-ExchangeOnline first with message-trace RBAC rights. Substitute the example addresses. This example limits the query to the last 24 hours.", "source": "https://learn.microsoft.com/en-us/powershell/module/exchange/get-messagetracev2", "sourceLabel": "Exchange Online official documentation", "rows": [["$end = Get-Date\n$start = $end.AddHours(-24)", "Define a bounded search window"], ["Get-MessageTraceV2 -SenderAddress 'sender@example.com' -StartDate $start -EndDate $end", "Find messages from a sender"], ["Get-MessageTraceDetailV2 -MessageTraceId '<trace-guid>' -RecipientAddress 'recipient@example.com'", "Inspect events for one recipient"], ["Disconnect-ExchangeOnline -Confirm:$false", "End the investigation session"]], "walkthrough": ["Use the reported delivery time and check time zones. V2 tracing supports up to 90 days of history, with at most a 10-day range per query; this example uses one day.", "Inspect recipient, received time, status and MessageTraceId. A bounded result set may need further filtering; do not infer that the first returned message is the reported one.", "Replace the trace GUID with MessageTraceId from the previous result. Review the event sequence and any policy or transport explanation for that exact recipient.", "Record only required trace identifiers and the disposition. A delivered transport status does not prove a person read the message or that a client displayed it."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "azure-subscription-and-resource-inventory", "title": "Azure subscription and resource inventory", "product": "Azure", "vendor": "Azure", "category": "Cloud", "description": "Check CLI context and inventory resources in the intended subscription.", "scope": "Azure CLI 2.x with Azure Resource Manager read permissions.", "prerequisites": "Install Azure CLI through your approved process. Sign in to your authorized tenant. Reader access is sufficient for most inventory queries.", "source": "https://learn.microsoft.com/en-us/cli/azure/account", "sourceLabel": "Azure official documentation", "rows": [["az login", "Authenticate interactively"], ["az account show --output table", "Inspect active subscription"], ["az account list --output table", "List available subscriptions"], ["az resource list --output table", "Inventory current-subscription resources"]], "walkthrough": ["Choose the intended tenant and account during sign-in. Authentication does not guarantee access to every subscription.", "Confirm tenant ID, subscription ID and account. Stop before resource queries if the active subscription is not the intended one.", "Use the subscription identifiers to distinguish similarly named environments. To switch intentionally, use az account set --subscription <subscription-id>; this changes local CLI context.", "Inspect resource type, name and resource group. An empty inventory may mean the wrong context or limited RBAC visibility rather than no deployed resources."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "azure-virtual-network-inspection", "title": "Azure virtual network inspection", "product": "Azure", "vendor": "Azure", "category": "Cloud", "description": "Inspect virtual networks, subnets and security group inventory.", "scope": "Azure CLI 2.x; Azure networking resource read access.", "prerequisites": "Run az login and verify az account show. Replace rg-example and vnet-example with your resource names.", "source": "https://learn.microsoft.com/en-us/cli/azure/network/vnet", "sourceLabel": "Azure official documentation", "rows": [["az network vnet list --output table", "List virtual networks"], ["az network vnet subnet list --resource-group rg-example --vnet-name vnet-example --output table", "Inspect subnets"], ["az network nsg list --output table", "List network security groups"], ["az network route-table list --output table", "Inventory custom route tables"]], "walkthrough": ["Compare VNet address spaces and resource groups. Overlapping address spaces matter for peering and connectivity, even when each VNet works in isolation.", "Replace both resource names. Check subnet ranges and associations against your topology; the list alone does not establish that a VM is attached as expected.", "Identify NSGs in the subscription. Existence is not enforcement: inspect subnet and NIC associations and effective rules for the affected endpoint.", "Inspect route tables associated with the affected subnet. These resource definitions do not include all effective system or learned routes on a VM NIC."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "sophos-firewall-cli-health-checks", "title": "Sophos Firewall CLI health checks", "product": "Sophos", "vendor": "Sophos", "category": "Cybersecurity", "description": "Gather appliance version, uptime and resource diagnostics in Device Console.", "scope": "Sophos Firewall SFOS Device Console, diagnostics syntax documented for 23.0. Not Sophos UTM or Advanced Shell.", "prerequisites": "Connect through approved console or SSH access and select Device Console. Confirm command availability with built-in help for your SFOS release.", "source": "https://docs.sophos.com/nsg/sophos-firewall/23.0/Help/en-us/webhelp/onlinehelp/CommandLineHelp/DeviceConsole/SystemCommands/Diagnostics/index.html", "sourceLabel": "Sophos official documentation", "rows": [["system diagnostics show version-info", "Identify appliance and firmware"], ["system diagnostics show uptime", "Read system uptime"], ["system diagnostics show memory", "Inspect memory diagnostics"], ["system diagnostics show disk", "Inspect disk diagnostics"]], "walkthrough": ["Record the model, serial and firmware build. In an HA investigation compare both members before considering version-related behavior.", "Compare uptime with reported interruption times. Uptime is a clue about a restart; it does not explain why a restart happened.", "Capture the current memory picture and compare with a baseline for the same appliance. A single reading is insufficient to identify a leak.", "Review storage figures and errors alongside logs. Do not remove files from Advanced Shell based only on a utilization reading."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "sophos-firewall-traffic-investigation", "title": "Sophos Firewall traffic investigation", "product": "Sophos", "vendor": "Sophos", "category": "Cybersecurity", "description": "Use log filters to connect a connection failure with firewall decisions.", "scope": "Sophos Firewall SFOS web admin console; labels vary by version.", "prerequisites": "Use a read-capable administrator account and a known source, destination and incident time. Availability of traffic records depends on rule logging.", "source": "https://docs.sophos.com/nsg/sophos-firewall/21.5/Help/en-us/webhelp/onlinehelp/AdministratorHelp/Logs/", "sourceLabel": "Sophos official documentation", "rows": [["Log viewer \u2192 Firewall", "Open firewall traffic logs"], ["Filter source IP, destination IP and destination port", "Isolate a traffic flow"], ["Inspect action, rule ID and reason", "Read the firewall decision"], ["Compare with VPN and system events", "Correlate adjacent failures"]], "walkthrough": ["Set the time window for the reported failure. Confirm that the relevant firewall rule is configured to log traffic before treating an empty log as evidence of no traffic.", "Use the translated and original addresses as appropriate to the scenario. Match the exact protocol and port; ping is not a substitute for an application flow.", "Record the matching rule and drop reason. An allow record shows a policy decision at this device, not successful application authentication or the return route.", "If the destination is across a VPN, compare tunnel events and route state at the same timestamp. Preserve findings before proposing a scoped change."], "kind": "Console path", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "juniper-junos-cli-essentials", "title": "Juniper Junos CLI essentials", "product": "Juniper", "vendor": "Juniper", "category": "Networking", "description": "Get oriented in Junos operational mode and inspect the chassis.", "scope": "Junos OS operational mode, prompt ending in >. Output differs by platform.", "prerequisites": "Use an authorized read-only operational login. These show commands do not require entering configuration mode.", "source": "https://www.juniper.net/documentation/us/en/software/junos/cli-reference/index.html", "sourceLabel": "Juniper official documentation", "rows": [["show version", "Identify software and model"], ["show interfaces terse", "Inspect interface summary"], ["show chassis hardware", "Inspect hardware inventory"], ["show chassis alarms", "Read active chassis alarms"]], "walkthrough": ["Record the Junos release and hardware model. Consult the command reference for that release before applying examples from another Juniper platform.", "Compare Admin and Link separately, then inspect protocol addresses on logical interfaces. Physical link up does not prove Layer 3 adjacency.", "Match installed modules and transceivers with the cabling plan. Empty or absent slots can be intentional; compare against expected inventory.", "Capture alarm severity, description and timestamp. Use model-specific guidance to distinguish environmental faults from expected conditions."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "juniper-routes-and-neighbor-checks", "title": "Juniper routes and neighbor checks", "product": "Juniper", "vendor": "Juniper", "category": "Networking", "description": "Inspect routes, ARP entries and discovered neighbors in Junos.", "scope": "Junos operational mode; LLDP and routing-instance behavior depend on configuration.", "prerequisites": "Use an operational read account. Confirm whether the workload uses the default routing table or a separate routing instance.", "source": "https://www.juniper.net/documentation/us/en/software/junos/cli-reference/index.html", "sourceLabel": "Juniper official documentation", "rows": [["show route", "Inspect the routing table"], ["show arp no-resolve", "Inspect IPv4 neighbor mappings"], ["show lldp neighbors", "Read adjacent device information"], ["show interfaces extensive", "Inspect detailed interface counters"]], "walkthrough": ["Identify the active route marker, protocol and next hop. For non-default routing instances, inspect the correct table rather than assuming the global table applies.", "Compare learned neighbors with directly attached subnets. no-resolve avoids DNS name lookup and keeps the output focused on addresses.", "Map local and remote ports to the cabling plan. Empty output can mean LLDP is disabled or unsupported on either endpoint.", "Focus on the affected interface and compare error trends over time. This broad command can produce large output; use an interface-specific form after locating the port."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "ubiquiti-unifi-device-connectivity", "title": "Ubiquiti UniFi device connectivity", "product": "Ubiquiti", "vendor": "Ubiquiti", "category": "Networking", "description": "Follow adoption and management connectivity through the UniFi console.", "scope": "UniFi Network application; excludes EdgeOS and airMAX CLI.", "prerequisites": "Use access to the correct UniFi site. Menu labels depend on the Network release. Avoid readopting or resetting devices while collecting evidence.", "source": "https://help.ui.com/hc/en-us/articles/7258465146519-Troubleshooting-UniFi-Device-Connectivity", "sourceLabel": "Ubiquiti official documentation", "rows": [["UniFi Network \u2192 Devices", "Locate the affected device"], ["Device details \u2192 IP address and uplink", "Inspect the management path"], ["Upstream switch \u2192 Ports \u2192 Port Manager", "Review VLAN and link settings"], ["Check console reachability and required ports", "Validate the management dependency"]], "walkthrough": ["Confirm the site, MAC address, model and displayed status. An offline device may still be forwarding traffic while its management path is unavailable.", "Compare management IP, VLAN and upstream port with the intended topology. An APIPA address indicates that the device did not obtain the expected DHCP address.", "Compare native and tagged networks on the uplink with the management VLAN. Inspect settings without applying a new port profile during diagnosis.", "Use the official UniFi required-ports reference for your deployment. Test only relevant paths; do not broadly open inter-VLAN traffic to make adoption work."], "kind": "Console path", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "ubiquiti-unifi-switch-port-checks", "title": "Ubiquiti UniFi switch port checks", "product": "Ubiquiti", "vendor": "Ubiquiti", "category": "Networking", "description": "Inspect switch port state, VLAN assignment and PoE budget.", "scope": "UniFi Network managed switches; port capabilities vary by model.", "prerequisites": "Use an authorized UniFi Network administrator with visibility into the correct site. Record the device and port before inspecting settings.", "source": "https://help.ui.com/hc/en-us/articles/33402927617047-UniFi-Switch-Settings", "sourceLabel": "Ubiquiti official documentation", "rows": [["Devices \u2192 Switch \u2192 Ports \u2192 Port Manager", "Find the physical port"], ["Inspect link state and negotiated speed", "Check the physical link"], ["Review native VLAN and tagged VLAN management", "Check network assignment"], ["Review PoE state and device power budget", "Check power delivery"]], "walkthrough": ["Match the connected endpoint and port number with your cabling map. Do not rely solely on a remembered client name or stale discovery entry.", "Compare the negotiated rate with both endpoint capabilities. A lower rate can reflect cable faults, negotiation or a legitimate endpoint limitation.", "Verify the untagged network and allowed tagged networks against the endpoint role. An access device and an AP carrying multiple SSIDs need different VLAN behavior.", "For PoE-capable models, compare endpoint demand and remaining switch budget. Do not power-cycle a production endpoint merely to see whether it recovers."], "kind": "Console path", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "hpe-proliant-ilo-health-overview", "title": "HPE ProLiant iLO health overview", "product": "HPE", "vendor": "HPE", "category": "Infrastructure", "description": "Read ProLiant health and hardware events through iLO.", "scope": "HPE iLO 6 web interface on supported ProLiant servers; menus differ for iLO 4/5/7.", "prerequisites": "Use an iLO account with view permissions on the management network. Match the server serial number before investigating.", "source": "https://support.hpe.com/hpesc/public/docDisplay?docId=sd00002007en_us", "sourceLabel": "HPE official documentation", "rows": [["Information \u2192 Overview", "Confirm server identity and health"], ["Information \u2192 Integrated Management Log", "Inspect hardware events"], ["System Information \u2192 Fans / Temperatures", "Inspect cooling status"], ["System Information \u2192 Power", "Inspect power redundancy"]], "walkthrough": ["Compare product name, serial number, power state and overall health with the asset record. Information for a powered-off server may reflect its last powered-on state.", "Read event severity and timestamps around the incident. Do not clear the IML before preserving the events needed for support.", "Compare failed sensors and thermal readings with the server-specific limits. Fan speed alone does not identify the failing component.", "Check power supply presence and status against the intended redundancy configuration. A disconnected redundant feed should be investigated before any physical maintenance."], "kind": "Console path", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "hpe-aruba-cx-switching-essentials", "title": "HPE Aruba CX switching essentials", "product": "HPE", "vendor": "HPE", "category": "Networking", "description": "Inspect AOS-CX switch interfaces and VLANs with platform-specific commands.", "scope": "HPE Aruba Networking AOS-CX 10.13. Not Comware or ArubaOS-Switch.", "prerequisites": "Use a switch account permitted to run show commands. Port naming and command availability depend on the CX model.", "source": "https://arubanetworking.hpe.com/techdocs/AOS-CX/10.13/PDF/monitoring_8400.pdf", "sourceLabel": "HPE official documentation", "rows": [["show version", "Identify the CX software release"], ["show interface brief", "Inspect interface summary"], ["show vlan", "Inspect configured VLANs"], ["show lldp neighbor-info", "Inspect discovered neighbors"]], "walkthrough": ["Confirm that the device runs AOS-CX. Do not reuse these commands unmodified on Comware or AOS-S switches.", "Use the displayed interface names to find the uplink or endpoint port. Compare administrative state, link state and speed with expected operation.", "Compare VLAN IDs and membership with both ends of each trunk. A VLAN being defined does not prove that it is carried on the affected link.", "Map local ports to remote devices and ports. LLDP requires compatible configuration on the peer, so absent discovery is not itself proof of a broken link."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "dell-poweredge-idrac-health-checks", "title": "Dell PowerEdge iDRAC health checks", "product": "Dell", "vendor": "Dell", "category": "Infrastructure", "description": "Read PowerEdge identity, power state and hardware event history.", "scope": "iDRAC9 RACADM. Examples use local RACADM installed on the managed host.", "prerequisites": "Use an approved Dell RACADM installation with appropriate privileges. Remote RACADM connection options differ; never place passwords into shared command history.", "source": "https://downloads.dell.com/topicspdf/idrac_v4-22_cliguide_en-us.pdf", "sourceLabel": "Dell official documentation", "rows": [["racadm getsysinfo", "Inspect server and iDRAC identity"], ["racadm serveraction powerstatus", "Read server power state"], ["racadm getsel", "Read the System Event Log"], ["racadm lclog view", "Read Lifecycle Controller events"]], "walkthrough": ["Compare the service tag, model and management information with the asset under investigation. This helps prevent collecting results from the wrong host.", "The powerstatus action only reads the state. Do not substitute powercycle, hardreset or powerdown while diagnosing an active production host.", "Correlate hardware faults with the reported interruption and verify timestamps. Preserve SEL entries before any log clearing or component replacement.", "Compare configuration and lifecycle events with the incident timeline. A recent maintenance event can explain a hardware or firmware inventory change."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "dell-poweredge-hardware-inventory", "title": "Dell PowerEdge hardware inventory", "product": "Dell", "vendor": "Dell", "category": "Infrastructure", "description": "Capture firmware and hardware inventory before planning maintenance.", "scope": "iDRAC9 local RACADM; inventory detail depends on platform and collection state.", "prerequisites": "Use an authorized local RACADM session with inventory read permissions. These commands do not schedule firmware updates.", "source": "https://downloads.dell.com/topicspdf/idrac_v4-22_cliguide_en-us.pdf", "sourceLabel": "Dell official documentation", "rows": [["racadm getsysinfo", "Identify the system"], ["racadm getversion", "Read firmware versions"], ["racadm hwinventory", "Inspect component inventory"], ["racadm jobqueue view", "Inspect queued management jobs"]], "walkthrough": ["Record the service tag and model so that any subsequent support lookup uses the correct hardware family.", "Compare reported firmware versions with your approved baseline. Do not assume that every component shares the same release version.", "Review NIC, storage controller and other component identifiers. Inventory may reflect the most recent collection; compare with lifecycle events after hardware changes.", "Check whether existing jobs are pending before proposing maintenance. Viewing the queue does not cancel jobs or restart the host."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "dell-data-domain-capacity-and-health", "title": "Dell Data Domain capacity and health", "product": "Dell Data Domain", "vendor": "Dell Data Domain", "category": "Infrastructure", "description": "Inspect filesystem state, capacity and active protection-appliance alerts.", "scope": "Dell Data Domain / PowerProtect DD, DD OS CLI. Verify syntax for your installed DD OS version.", "prerequisites": "Use an authorized DD management account with read privileges. Preserve alerts and do not run clean, destroy or storage changes from a quick reference.", "source": "https://www.delltechnologies.com/asset/en-us/products/data-protection/technical-support/docu91804.pdf", "sourceLabel": "Dell Data Domain official documentation", "rows": [["system show version", "Identify DD OS release"], ["filesys status", "Inspect filesystem availability"], ["filesys show space", "Inspect physical and logical space"], ["alerts show current", "Read active appliance alerts"]], "walkthrough": ["Record the system software version and consult the matching command reference. Appliance capabilities and output fields vary between DD OS releases.", "Confirm the filesystem is running before treating a backup error as a client-only problem. A running state does not establish that capacity and integration are healthy.", "Distinguish pre-compression data from post-compression storage and available physical space. Deduplication ratios alone do not indicate usable headroom.", "Capture alert IDs and severity alongside the time of the backup failure. Investigate capacity, hardware and environmental alerts through the matching vendor runbook."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "dell-data-domain-replication-checks", "title": "Dell Data Domain replication checks", "product": "Dell Data Domain", "vendor": "Dell Data Domain", "category": "Infrastructure", "description": "Inspect replication contexts and distinguish idle replication from a stalled copy.", "scope": "DD OS replication CLI; context type and supported metrics vary by release.", "prerequisites": "Use authorized read access to the source and destination. Identify the replication context and expected schedule before judging lag.", "source": "https://www.dell.com/support/kbdoc/en-us/000043349/72419-replication-status", "sourceLabel": "Dell Data Domain official documentation", "rows": [["replication show config", "Identify configured replication contexts"], ["replication status", "Inspect replication state"], ["replication show performance rctx://<context-number>", "Read context throughput"], ["alerts show current", "Correlate replication with active alerts"]], "walkthrough": ["Match the source and destination paths to the protected workload. Configuration alone does not prove an active or healthy transfer.", "Check the intended context and compare state with expected activity. An idle context can be healthy when there is no new data to transfer.", "Replace the placeholder with a real context number from the configuration. Compare repeated samples with the source workload; a single zero sample is not proof of failure.", "Check both systems for capacity and connectivity-related alerts. Document the context, observed state and incident time before escalating."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "kali-nmap-discovery-essentials", "title": "Kali Nmap discovery essentials", "product": "Kali Linux", "vendor": "Kali Linux", "category": "Cybersecurity", "description": "Discover a lab host\u2019s exposed TCP services and interpret scan states.", "scope": "Kali Linux with Nmap 7.x. Examples use one explicitly authorized lab host.", "prerequisites": "Replace <lab-ip> with the address of a system you own or have permission to assess. These commands send network probes; agree on scope before scanning.", "source": "https://nmap.org/book/man.html", "sourceLabel": "Kali Linux official documentation", "rows": [["nmap --version", "Check the installed scanner version"], ["nmap -sn <lab-ip>", "Check host discovery responses"], ["nmap -sT -p 22,80,443 <lab-ip>", "Inspect three selected TCP ports"], ["nmap -sT -sV -p 22,80,443 <lab-ip>", "Identify services on selected ports"]], "walkthrough": ["Record the Nmap version and available libraries before following examples. Package versions can differ between Kali installations and rolling updates.", "Replace the placeholder with one approved target. Host discovery does not perform a port scan. A host marked down may simply block the discovery probes; it is not proof the machine is absent.", "This TCP connect scan checks only the listed ports. Open means a connection was accepted; closed and filtered have different meanings. Results reflect this source host and observation time.", "Service detection sends additional application probes. Treat product and version matches as evidence to verify with the service owner, not a definitive vulnerability finding."], "kind": "Command", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "kali-wireshark-packet-analysis", "title": "Kali Wireshark packet analysis", "product": "Kali Linux", "vendor": "Kali Linux", "category": "Cybersecurity", "description": "Use display filters to inspect DNS, TCP handshakes and one lab conversation.", "scope": "Wireshark desktop on Kali Linux. Examples are display filters, not capture filters.", "prerequisites": "Open a packet capture you are authorized to inspect using File \u2192 Open. Use an existing lab capture for this walkthrough; captures can contain credentials and personal data.", "source": "https://www.wireshark.org/docs/wsug_html_chunked/index.html", "sourceLabel": "Kali Linux official documentation", "rows": [["dns", "Display decoded DNS traffic"], ["tcp.flags.syn == 1 && tcp.flags.ack == 0", "Find initial TCP SYN packets"], ["ip.addr == 192.0.2.10", "Focus on one IPv4 endpoint"], ["tcp.stream eq 0", "Isolate a TCP conversation"]], "walkthrough": ["Enter dns in the display filter bar and apply it. Match query names, transaction IDs and responses. Encrypted DNS may not appear as ordinary decoded DNS packets.", "Look for the first step of a TCP handshake, then compare it with the reverse-direction response. Retransmissions alone do not establish whether a firewall or endpoint caused a failure.", "Replace the documentation address with the host in your capture. This matches either source or destination. A display filter hides unrelated packets without deleting them from the file.", "Replace 0 with the stream index of the selected connection, or use Follow \u2192 TCP Stream. TLS payload remains encrypted unless you have appropriate decryption material; export only approved data."], "kind": "Display filter", "level": "Beginner", "time": 7, "updated": "2026-11-02"}, {"id": "kali-burp-suite-proxy-basics", "title": "Kali Burp Suite proxy basics", "product": "Kali Linux", "vendor": "Kali Linux", "category": "Cybersecurity", "description": "Inspect requests from a local training application with Burp\u2019s built-in browser.", "scope": "Burp Suite Community or Professional desktop. Proxy inspection works without an automated scanner.", "prerequisites": "Start Burp with a temporary project and default settings. Use a local training application or a target you are explicitly authorized to test; keep personal browsing outside Burp\u2019s browser.", "source": "https://portswigger.net/burp/documentation/desktop/tools/proxy", "sourceLabel": "Kali Linux official documentation", "rows": [["Proxy \u2192 Intercept \u2192 Open Browser", "Launch the preconfigured test browser"], ["Proxy \u2192 Intercept \u2192 Intercept is off", "Allow ordinary browsing while recording"], ["Proxy \u2192 HTTP history", "Inspect a lab request and response"], ["Proxy \u2192 Intercept \u2192 Intercept is on \u2192 Forward", "Observe a paused request, then release it"]], "walkthrough": ["Open your approved training application in Burp\u2019s browser. This browser is already configured to use Burp\u2019s proxy, avoiding changes to your everyday browser\u2019s proxy and certificate settings.", "Keep interception off while navigating the lab so requests are not paused. HTTP history still records traffic that passes through the proxy.", "Select a request to your training app and compare the method, path, status and response headers. Apply filters to focus on the approved target and avoid collecting unrelated traffic.", "Trigger one harmless page request in the lab browser. Inspect it and click Forward without editing. Turn interception off when finished so later requests do not remain unexpectedly paused."], "kind": "Console path", "level": "Beginner", "time": 7, "updated": "2026-11-02"}];